def min_last_exam_day(n, exams):
    exams.sort(key=lambda x: x[1])  # Sort exams by the early date
    current_day = 0
    for a, b in exams:
        if b > current_day:
            current_day = b
        else:
            current_day = max(current_day + 1, a)
    return current_day

# Example usage:
n = int(input())
exams = [tuple(map(int, input().split())) for _ in range(n)]
print(min_last_exam_day(n, exams))

